-- Phase 7 Part 4: maintenance SLA breaches (recorded by the database, scheduled through the outbox).
-- Generated by prisma migrate diff, followed by a hand-written section.

-- AlterEnum
ALTER TYPE "MaintenanceEventType" ADD VALUE 'SLA_BREACHED';

-- AlterTable
ALTER TABLE "maintenance_requests" ADD COLUMN     "resolution_breached_at" TIMESTAMPTZ(3),
ADD COLUMN     "response_breached_at" TIMESTAMPTZ(3);


-- =============================================================================================
-- Hand-written below this line: SLA breaches. A breach is recorded once, only by the database
-- and only when it is true (the target passed unmet); a priority change that moves the target
-- into the future clears it. Due times are scheduled through the outbox (relayed to the worker,
-- ARCHITECTURE section 5); the worker's job calls app_maintenance_check_breach in the tenant's
-- context. See docs/architecture/DATA_MODEL.md section 7 (Maintenance). The new enum value is
-- only used inside function bodies (checked when they run).
-- =============================================================================================

-- The request guard of migration 20261114090000_maintenance, plus the breach columns.
CREATE OR REPLACE FUNCTION app_maintenance_request_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text := OLD."status" || '>' || NEW."status";
  needs_note boolean;
  want_response_breach boolean := OLD."response_breached_at" IS NULL AND NEW."response_breached_at" IS NOT NULL;
  want_resolution_breach boolean := OLD."resolution_breached_at" IS NULL AND NEW."resolution_breached_at" IS NOT NULL;
BEGIN
  IF OLD."status" IN ('CLOSED', 'REJECTED', 'CANCELLED') THEN
    RAISE EXCEPTION 'maintenance request % is % and no longer changes', OLD."id", lower(OLD."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  -- The report itself never changes.
  IF (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."common_area_id", NEW."request_number",
      NEW."title", NEW."description", NEW."location_detail", NEW."submitted_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."common_area_id", OLD."request_number",
      OLD."title", OLD."description", OLD."location_detail", OLD."submitted_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'what was reported in maintenance request % never changes', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  -- Serialises with work orders of this request (see the work order triggers).
  PERFORM pg_advisory_xact_lock(hashtextextended('veyra.maintenance_request:' || OLD."id"::text, 0));

  -- Derived fields are owned by the database.
  NEW."accepted_by_user_id" := OLD."accepted_by_user_id";
  NEW."accepted_at" := OLD."accepted_at";
  NEW."resolved_at" := OLD."resolved_at";
  NEW."closed_at" := OLD."closed_at";
  NEW."reopen_count" := OLD."reopen_count";
  NEW."response_due_at" := OLD."response_due_at";
  NEW."resolution_due_at" := OLD."resolution_due_at";
  NEW."response_breached_at" := OLD."response_breached_at";
  NEW."resolution_breached_at" := OLD."resolution_breached_at";

  -- A breach is recorded only on its own, only once, and only when true right now.
  IF want_response_breach OR want_resolution_breach THEN
    IF NEW."status" <> OLD."status" OR NEW."priority" <> OLD."priority" OR NEW."category" <> OLD."category" THEN
      RAISE EXCEPTION 'a breach is recorded on its own' USING ERRCODE = 'check_violation';
    END IF;
    IF want_response_breach AND NOT (
         OLD."status" = 'SUBMITTED' AND OLD."response_due_at" IS NOT NULL AND now() >= OLD."response_due_at") THEN
      RAISE EXCEPTION 'the response target of request % has not been missed', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF want_resolution_breach AND NOT (
         OLD."status" IN ('SUBMITTED', 'ACCEPTED') AND OLD."resolution_due_at" IS NOT NULL
         AND now() >= OLD."resolution_due_at") THEN
      RAISE EXCEPTION 'the resolution target of request % has not been missed', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
    IF want_response_breach THEN NEW."response_breached_at" := now(); END IF;
    IF want_resolution_breach THEN NEW."resolution_breached_at" := now(); END IF;
    NEW."status_note" := OLD."status_note";
    RETURN NEW;
  END IF;

  IF NEW."priority" IS DISTINCT FROM OLD."priority" THEN
    NEW := app_maintenance_set_due(NEW);
    -- A target moved into the future is not missed (any more).
    IF NEW."response_due_at" IS NULL OR NEW."response_due_at" > now() THEN
      NEW."response_breached_at" := NULL;
    END IF;
    IF NEW."resolution_due_at" IS NULL OR NEW."resolution_due_at" > now() THEN
      NEW."resolution_breached_at" := NULL;
    END IF;
  END IF;

  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    RETURN NEW;
  END IF;
  IF transition NOT IN ('SUBMITTED>ACCEPTED', 'SUBMITTED>REJECTED', 'SUBMITTED>CANCELLED',
                        'ACCEPTED>RESOLVED', 'ACCEPTED>CANCELLED',
                        'RESOLVED>CLOSED', 'RESOLVED>ACCEPTED') THEN
    RAISE EXCEPTION 'a maintenance request cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  needs_note := transition IN ('SUBMITTED>REJECTED', 'SUBMITTED>CANCELLED', 'ACCEPTED>CANCELLED', 'RESOLVED>ACCEPTED');
  IF needs_note AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'give a reason to % this request',
      CASE transition WHEN 'SUBMITTED>REJECTED' THEN 'reject' WHEN 'RESOLVED>ACCEPTED' THEN 'reopen' ELSE 'cancel' END
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT needs_note THEN
    NEW."status_note" := NULL;
  END IF;

  IF transition = 'ACCEPTED>RESOLVED' AND NOT (
       EXISTS (SELECT 1 FROM "work_orders" WHERE "request_id" = OLD."id" AND "status" = 'COMPLETED')
       AND NOT EXISTS (SELECT 1 FROM "work_orders" WHERE "request_id" = OLD."id"
                                                 AND "status" NOT IN ('COMPLETED', 'CANCELLED'))) THEN
    RAISE EXCEPTION 'a request is resolved once its work is completed and no work is still open'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" = 'CANCELLED' AND EXISTS (
       SELECT 1 FROM "work_orders" WHERE "request_id" = OLD."id" AND "status" NOT IN ('COMPLETED', 'CANCELLED')) THEN
    RAISE EXCEPTION 'cancel the open work orders of this request first' USING ERRCODE = 'check_violation';
  END IF;

  IF transition = 'SUBMITTED>ACCEPTED' THEN
    NEW."accepted_at" := now();
    NEW."accepted_by_user_id" := app_current_user_id();
  ELSIF NEW."status" = 'RESOLVED' THEN
    NEW."resolved_at" := now();
  ELSIF NEW."status" = 'CLOSED' THEN
    NEW."closed_at" := now();
  ELSIF transition = 'RESOLVED>ACCEPTED' THEN
    NEW."resolved_at" := NULL;
    NEW."reopen_count" := OLD."reopen_count" + 1;
  END IF;
  RETURN NEW;
END
$$;

-- Due times to watch: one outbox event per target, available when it falls due. Ids only.
CREATE FUNCTION app_maintenance_schedule_sla(r "maintenance_requests") RETURNS void
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF r."response_due_at" IS NOT NULL AND r."status" = 'SUBMITTED' THEN
    INSERT INTO "outbox_events" ("id", "organisation_id", "type", "payload", "available_at")
    VALUES (gen_random_uuid(), r."organisation_id", 'maintenance.sla.due',
            jsonb_build_object('requestId', r."id", 'propertyId', r."property_id", 'target', 'RESPONSE',
                               'dueAt', to_char(r."response_due_at" AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
            r."response_due_at");
  END IF;
  IF r."resolution_due_at" IS NOT NULL AND r."status" IN ('SUBMITTED', 'ACCEPTED') THEN
    INSERT INTO "outbox_events" ("id", "organisation_id", "type", "payload", "available_at")
    VALUES (gen_random_uuid(), r."organisation_id", 'maintenance.sla.due',
            jsonb_build_object('requestId', r."id", 'propertyId', r."property_id", 'target', 'RESOLUTION',
                               'dueAt', to_char(r."resolution_due_at" AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
            r."resolution_due_at");
  END IF;
END
$$;

-- The history trigger of migration 20261114090000_maintenance, plus breaches and scheduling.
CREATE OR REPLACE FUNCTION app_maintenance_request_log() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'STATUS_CHANGED',
                                'RESIDENT', NULL, NEW."status"::text, NULL);
    PERFORM app_maintenance_schedule_sla(NEW);
    RETURN NULL;
  END IF;
  IF NEW."status" IS DISTINCT FROM OLD."status" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'STATUS_CHANGED',
                                'RESIDENT', OLD."status"::text, NEW."status"::text, NEW."status_note");
  END IF;
  IF NEW."priority" IS DISTINCT FROM OLD."priority" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'PRIORITY_CHANGED',
                                'RESIDENT', OLD."priority"::text, NEW."priority"::text, NULL);
  END IF;
  IF (NEW."response_due_at", NEW."resolution_due_at") IS DISTINCT FROM (OLD."response_due_at", OLD."resolution_due_at") THEN
    PERFORM app_maintenance_schedule_sla(NEW);
  END IF;
  IF OLD."response_breached_at" IS NULL AND NEW."response_breached_at" IS NOT NULL THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'SLA_BREACHED',
                                'INTERNAL', NULL, 'RESPONSE', NULL);
  END IF;
  IF OLD."resolution_breached_at" IS NULL AND NEW."resolution_breached_at" IS NOT NULL THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."id", NULL, 'SLA_BREACHED',
                                'INTERNAL', NULL, 'RESOLUTION', NULL);
  END IF;
  RETURN NULL;
END
$$;

-- Called by the worker in the tenant's context when a due time arrives. True when it recorded a
-- breach; false when the target was met, moved, or already recorded. Safe to call any number of
-- times (the guard re-checks everything).
CREATE FUNCTION app_maintenance_check_breach(request uuid, target text, due timestamptz) RETURNS boolean
  LANGUAGE plpgsql
  AS $$
DECLARE
  r record;
BEGIN
  SELECT "status", "response_due_at", "resolution_due_at", "response_breached_at", "resolution_breached_at"
    INTO r FROM "maintenance_requests" WHERE "id" = request FOR UPDATE;
  IF NOT FOUND OR now() < due THEN
    RETURN false;
  END IF;
  IF target = 'RESPONSE' AND r."status" = 'SUBMITTED' AND r."response_due_at" = due
     AND r."response_breached_at" IS NULL THEN
    UPDATE "maintenance_requests" SET "response_breached_at" = now() WHERE "id" = request;
    RETURN true;
  END IF;
  IF target = 'RESOLUTION' AND r."status" IN ('SUBMITTED', 'ACCEPTED') AND r."resolution_due_at" = due
     AND r."resolution_breached_at" IS NULL THEN
    UPDATE "maintenance_requests" SET "resolution_breached_at" = now() WHERE "id" = request;
    RETURN true;
  END IF;
  RETURN false;
END
$$;

GRANT EXECUTE ON FUNCTION app_maintenance_check_breach(uuid, text, timestamptz) TO veyra_app;
